-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Accumulating misstatements above clearly-trivial threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Logistics Corp., the engagement team identifies expense misstatements totaling $18,500. The auditor set overall materiality at $200,000 and the threshold for clearly trivial items at $4,000. Under AU-C 450, the auditor''s appropriate action regarding these misstatements is to:', '["Disregard the misstatements because they are below overall materiality", "Accumulate the misstatements and request management to correct them", "Report the misstatements directly to those charged with governance without notifying management", "Treat the misstatements as clearly trivial because no single item exceeds materiality"]'::jsonb, 1, 'Under AU-C 450.08-.09, the auditor must accumulate all identified misstatements other than those that are clearly trivial and communicate them to the appropriate level of management with a request for correction. Because the $18,500 total exceeds the $4,000 clearly trivial threshold, these misstatements must be accumulated. Disregarding them (choice A) is incorrect because being below materiality does not mean the auditor can ignore misstatements that exceed the clearly trivial threshold.', 'medium', 2),

-- Q2: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["A control is designed or operated in a way that does not allow timely prevention or detection of misstatements", "The auditor identifies a material misstatement in the financial statements during testing", "Management fails to implement all recommendations from the prior year''s audit", "The entity does not maintain a formal internal audit department"]'::jsonb, 0, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent, or detect and correct, misstatements on a timely basis. Choice B is incorrect because a material misstatement finding may indicate a control deficiency but is not itself the definition—a deficiency focuses on the control''s ability to function, not on whether an error has already occurred.', 'easy', 1),

-- Q3: easy / L2 — Classifying a misstatement from misapplied capitalization policy
(1, 'Misstatements and Control Deficiencies', 'Brookfield Retail Inc. capitalized $12,000 in routine maintenance costs as leasehold improvements on its December 2025 financial statements. Under AU-C 450, this misstatement is best classified as:', '["A projected misstatement extrapolated from a sample of transactions", "A judgmental misstatement arising from management''s subjective estimate", "A factual misstatement about which there is no doubt", "A likely misstatement that requires statistical confirmation"]'::jsonb, 2, 'Under AU-C 450.A4, a factual misstatement is one about which there is no doubt. Capitalizing routine maintenance costs clearly violates GAAP, making the $12,000 error a factual misstatement with no subjective judgment involved. A judgmental misstatement (choice B) is incorrect because no estimate or subjective assessment was involved—management simply misapplied the capitalization policy to an expense item.', 'easy', 2),

-- Q4: medium / L3 — Analyzing design vs. operation deficiency implications
(1, 'Misstatements and Control Deficiencies', 'Silverline Manufacturing''s accounts payable department has a policy requiring two-person approval for all payments exceeding $10,000. During the audit, Martinez & Hall CPAs discover that while the policy exists, the system allows single-person approval when the second approver is unavailable. The most likely effect on the auditor''s assessment is:', '["The deficiency is immaterial because the policy itself is properly designed", "The auditor should reclassify this as a fraud risk factor rather than a control deficiency", "The deficiency affects only assertions related to completeness of accounts payable", "The operating deficiency increases the risk of unauthorized payments being processed"]'::jsonb, 3, 'Under AU-C 265.A1, a deficiency in operation exists when a properly designed control does not operate as designed. Although Silverline''s approval policy is well designed, the system override creates an operating deficiency that increases the risk of unauthorized disbursements. Choice A is incorrect because a properly designed control that fails in operation still constitutes a deficiency—design adequacy does not excuse operational failures.', 'medium', 3),

-- Q5: easy / L1 — Clearly trivial misstatements concept
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, misstatements classified as clearly trivial are those that:', '["Fall below overall materiality but above performance materiality", "Are individually and in the aggregate wholly inconsequential to the financial statements", "Management has agreed to correct before issuing the financial statements", "Do not involve cash or revenue accounts"]'::jsonb, 1, 'Under AU-C 450.A2, clearly trivial misstatements are those that are clearly inconsequential, whether taken individually or in the aggregate and whether judged by any criteria of size, nature, or circumstances. The auditor need not accumulate these items. Choice A is incorrect because it confuses the clearly trivial threshold with performance materiality—clearly trivial is a much lower bar set well below materiality.', 'easy', 1),

-- Q6: hard / L4 — Evaluating opinion modification for material uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Evergreen Financial Group, the auditor identifies $340,000 in uncorrected misstatements across revenue recognition and loan loss reserves. Overall materiality is $300,000. Management argues the misstatements are offset by conservative estimates in other areas and refuses correction. The engagement partner must evaluate whether the financial statements are materially misstated. Under AU-C 450 and AU-C 705, the most appropriate course of action is to:', '["Issue a qualified or adverse opinion because the uncorrected misstatements exceed overall materiality regardless of management''s offsetting argument", "Accept management''s position if the conservative estimates can be independently verified", "Issue an unmodified opinion with an emphasis-of-matter paragraph describing the uncorrected misstatements", "Withdraw from the engagement because management''s refusal indicates a scope limitation"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material individually or in the aggregate. Management cannot offset identified misstatements with conservative estimates in unrelated areas because each misstatement must be evaluated on its own merits. Since $340,000 exceeds the $300,000 materiality threshold, AU-C 705 requires a qualified or adverse opinion. Accepting management''s offsetting argument (choice B) is incorrect because misstatements in one area cannot be netted against potential overstatements in another.', 'hard', 4),

-- Q7: medium / L3 — IT general control deficiency cascading to application controls
(1, 'Misstatements and Control Deficiencies', 'Cedar Valley Hospital relies on an ERP system for billing and collections. During the audit, Tanaka & Associates discovers that the IT department has not restricted programmer access to the production environment, allowing developers to modify billing rates without approval. The most likely effect on the auditor''s assessment is:', '["The deficiency affects only the IT general control environment and does not impact financial statement assertions", "The auditor should report this as a fraud finding rather than a control deficiency", "Application controls dependent on the ERP system may be unreliable, requiring expanded substantive testing of revenue", "The deficiency is limited to the change management process and does not affect billing accuracy"]'::jsonb, 2, 'Under AU-C 315.A67, IT general controls support the continued proper functioning of application controls. When programmer access to production is unrestricted, any application control dependent on that system—including billing rate calculations—may be compromised, requiring expanded substantive testing. Choice A is incorrect because IT general control deficiencies directly undermine the reliability of application controls that process financial transactions.', 'medium', 3),

-- Q8: medium / L2 — Setting the clearly trivial posting threshold
(1, 'Misstatements and Control Deficiencies', 'Redstone Construction Corp. has overall materiality of $150,000 and performance materiality of $112,500. The engagement partner establishes a threshold for clearly trivial misstatements. Under AU-C 450, the most appropriate basis for setting this threshold is:', '["A fixed amount equal to 50% of performance materiality", "A prescribed amount equal to 25% of overall materiality per AU-C 450", "Any misstatement amount that falls below performance materiality", "A judgment-based amount set considerably below overall materiality"]'::jsonb, 3, 'Under AU-C 450.A2, the clearly trivial threshold should be set at an amount below which misstatements would be clearly inconsequential to the financial statements. The standard does not prescribe a specific formula, leaving the determination to the auditor''s professional judgment—typically set considerably below overall materiality. Choice B is incorrect because AU-C 450 does not mandate any specific percentage; firms establish this threshold based on engagement-specific circumstances.', 'medium', 2),

-- Q9: hard / L4 — Action when governance structure is compromised by material weakness
(1, 'Misstatements and Control Deficiencies', 'While auditing Grand Meridian Hotels, Parker & Lee CPAs identify a material weakness involving the CEO''s routine override of internal controls. The CEO also serves as board chair, and the three-member board includes two directors with close personal ties to the CEO. The engagement partner must determine the appropriate communication approach. Under AU-C 265 and AU-C 260, the auditor should:', '["Communicate the material weakness only in writing to the full board and document the CEO''s response", "Consider whether the governance structure limitations require communication to regulatory authorities or modification of the audit report", "Report the material weakness to the entity''s external legal counsel as an alternative to the board", "Withdraw from the engagement because the lack of independent governance makes communication futile"]'::jsonb, 1, 'Under AU-C 265.13 and AU-C 260.A38, when those charged with governance are involved in the control deficiency or when governance independence is compromised, the auditor must consider the implications for the audit, including whether the situation requires reporting to regulatory authorities or affects the audit opinion. Choice A is incorrect because communicating only to the full board is insufficient when the board itself lacks the independence to act on the material weakness effectively.', 'hard', 4),

-- Q10: medium / L2 — Reassessing risk when misstatements found in one area
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Energy Partners, the auditor discovers $45,000 in misstatements in the fixed assets account from systematic errors in depreciation calculations. Performance materiality is $80,000. Under AU-C 450, the auditor should consider whether:', '["The misstatements indicate that additional misstatements may exist in related accounts, warranting expanded testing", "The depreciation misstatements should be immediately reported as a material weakness to those charged with governance", "The engagement should be terminated due to unreliable accounting records", "The performance materiality level must be formally reduced by the exact amount of misstatements found"]'::jsonb, 0, 'Under AU-C 450.A6, when the auditor identifies misstatements, the auditor should consider whether their nature and pattern indicate that additional misstatements may exist that could be material when aggregated with identified misstatements. Systematic depreciation errors may signal broader weaknesses in fixed asset accounting. Choice D is incorrect because AU-C 450 does not require mechanical reduction of performance materiality by the exact misstatement amount found.', 'medium', 2),

-- Q11: medium / L2 — Written representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Granite Peak Investments, the auditor has accumulated $22,000 in uncorrected misstatements that management declined to adjust. Overall materiality is $100,000. Under AU-C 450, the auditor should obtain from management:', '["A signed engagement letter amendment acknowledging the uncorrected misstatements", "An oral acknowledgment during the closing conference that the misstatements are immaterial", "Written representations that management believes the uncorrected misstatements are immaterial to the financial statements as a whole", "A formal board resolution approving the financial statements with the known misstatements"]'::jsonb, 2, 'Under AU-C 450.14, the auditor must request written representations from management that it believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items should be included in or attached to the representation letter. Choice B is incorrect because AU-C 450 specifically requires written representations—an oral acknowledgment at a closing conference does not satisfy this requirement.', 'medium', 2),

-- Q12: medium / L2 — Qualitative assessment of an intentional misstatement
(1, 'Misstatements and Control Deficiencies', 'While auditing Coastal Ventures LLC, the engagement team discovers that the controller intentionally recorded $8,000 in personal expenses as business travel. Overall materiality is $250,000. Under AU-C 450, the auditor''s evaluation of this misstatement should consider:', '["Only the quantitative impact, which at $8,000 is clearly trivial relative to materiality", "Whether the $8,000 amount is large enough to require restatement of prior-period financial statements", "Whether the misstatement can be offset against other overstatements in the travel account", "The qualitative characteristics of the misstatement, including that it is intentional and may indicate fraud"]'::jsonb, 3, 'Under AU-C 450.A16, the auditor must consider both quantitative and qualitative factors when evaluating uncorrected misstatements. An intentional misstatement—regardless of amount—raises concerns about management integrity and potential fraud under AU-C 240, requiring further investigation. Choice A is incorrect because focusing solely on the dollar amount ignores the qualitative significance of an intentional misstatement, which may indicate broader issues with the control environment.', 'medium', 2),

-- Q13: hard / L4 — Prior-period uncorrected misstatements affecting current year
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brightwater Technologies for the year ended December 31, 2025, the engagement team notes that $65,000 in uncorrected misstatements from the 2024 audit relate to an overstatement of prepaid insurance that has now reversed into 2025 expense. Overall materiality for 2025 is $120,000. The engagement partner must evaluate the effect on the current year''s financial statements. The most appropriate conclusion is that:', '["The reversal eliminates any concern because the 2025 financial statements self-correct over time", "The prior-period misstatement must be included in the 2025 aggregate of uncorrected misstatements because it affects current-year insurance expense", "The auditor should require a prior-period adjustment regardless of the misstatement''s materiality", "The misstatement should be excluded from the 2025 evaluation because it originated in a prior year"]'::jsonb, 1, 'Under AU-C 450.10, the auditor must evaluate the effect of uncorrected misstatements from prior periods on the current period''s financial statements. The 2024 prepaid insurance overstatement reverses into understated 2025 expense, affecting the current year''s income statement and must be included in the aggregate evaluation. Choice A is incorrect because while the balance sheet may self-correct, the income statement effects in both years remain misstated, requiring continued evaluation.', 'hard', 4),

-- Q14: medium / L3 — Control deficiency impact on substantive testing
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeview Medical Center, Chen & Associates identifies a significant deficiency in the revenue cycle: patient billing adjustments over $5,000 lack supervisory review. The auditor must determine the effect on planned audit procedures. The most likely impact is that the auditor will:', '["Increase the extent of substantive testing of billing adjustments and revenue accounts", "Reduce reliance on analytical procedures but maintain the same sample sizes for detail testing", "Communicate the deficiency to management and take no further action regarding audit testing", "Limit additional testing to billing adjustments exceeding the $5,000 threshold only"]'::jsonb, 0, 'Under AU-C 330.A20, when control deficiencies are identified, the auditor must consider the effect on the nature, timing, and extent of substantive procedures. A significant deficiency in supervisory review of billing adjustments increases the risk of material misstatement, requiring expanded substantive testing. Choice C is incorrect because identifying and communicating a deficiency does not relieve the auditor of the obligation to respond to the increased risk through additional procedures.', 'medium', 3),

-- Q15: medium / L3 — Fraud-related misstatement impact on control deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'While auditing Horizon Distribution Inc., the engagement team discovers that a warehouse manager fabricated $14,000 in fictitious overtime entries over six months. The existing payroll control requires supervisor approval, but the warehouse manager''s supervisor routinely approved timesheets without review. The most significant implication for the auditor''s evaluation is:', '["The misstatement is immaterial and requires no further control evaluation", "The warehouse manager''s actions constitute an isolated incident with no bearing on control effectiveness", "The supervisor''s failure to perform the review control is at least a significant deficiency because it allowed a fraud-related misstatement", "The auditor should reclassify the entire payroll function as a material weakness based solely on the dollar amount"]'::jsonb, 2, 'Under AU-C 265.A12, a control deficiency that allows a fraud-related misstatement to occur is at least a significant deficiency and may be a material weakness, regardless of the dollar amount. The supervisor''s failure to review timesheets represents a breakdown in operating effectiveness of a preventive control. Choice B is incorrect because fraud facilitated by a control failure cannot be dismissed as isolated without evaluating the control''s design and operation.', 'medium', 3),

-- Q16: easy / L1 — Timing of written communication of material weaknesses
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s written communication of significant deficiencies and material weaknesses to those charged with governance must be made:', '["Within 30 days of the audit report date", "Before the entity files its annual report with regulators", "Simultaneously with the delivery of the audit opinion", "No later than 60 days following the report release date"]'::jsonb, 3, 'Under AU-C 265.13, the auditor should communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This allows time for the auditor to finalize the evaluation while ensuring timely communication. Choice A is incorrect because the standard specifies a 60-day window, not 30 days, from the report release date.', 'easy', 1),

-- Q17: medium / L3 — Determining when a known misstatement should not be projected
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Ridge Hotels, the auditor tests a sample of 40 fixed asset additions from a population of 800 and finds a single $6,200 error where a capital lease was incorrectly classified. The auditor must determine whether to project this misstatement to the population. The most important factor in this decision is whether:', '["The $6,200 amount exceeds the clearly trivial threshold established for the engagement", "The misstatement is an anomaly unrepresentative of the population or is characteristic of a systematic error in lease classification", "The total population of fixed asset additions exceeds overall materiality", "Management has already agreed to correct the individual $6,200 misstatement"]'::jsonb, 1, 'Under AU-C 530.A18, the auditor must evaluate whether a detected misstatement is an anomaly—an isolated event not representative of the population—or indicative of a systematic error. If the lease classification error is truly unique and non-recurring, projection may not be appropriate; if it reflects a pattern, the error must be projected. Choice D is incorrect because management''s willingness to correct one item does not address whether similar errors exist in the untested population.', 'medium', 3),

-- Q18: easy / L1 — Management responsibility for correcting misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, primary responsibility for correcting misstatements identified during the audit rests with:', '["Management of the entity being audited", "The external auditor who identified the misstatements", "Those charged with governance of the entity", "The entity''s internal audit department"]'::jsonb, 0, 'Under AU-C 450.09, the auditor communicates all accumulated misstatements to the appropriate level of management and requests correction. Management bears primary responsibility for the preparation and fair presentation of the financial statements, including correcting identified errors. Choice B is incorrect because the auditor''s role is to identify and communicate misstatements, not to correct them—correction is a management responsibility.', 'easy', 1),

-- Q19: medium / L3 — Pervasive misstatements affecting planned audit approach
(1, 'Misstatements and Control Deficiencies', 'While auditing Cascade Manufacturing Corp., the engagement team identifies misstatements in inventory valuation, cost of goods sold, and accounts payable—all stemming from an error in the standard costing system. Performance materiality is $90,000 and the aggregate misstatements total $72,000. The most likely effect on the auditor''s planned approach is that the auditor will:', '["Issue an adverse opinion because the misstatements are pervasive across multiple accounts", "Reduce the scope of remaining audit procedures since the root cause has been identified", "Reassess risk for assertions affected by the standard costing system and expand testing in those areas", "Require management to engage a specialist to recalculate all standard costs before continuing"]'::jsonb, 2, 'Under AU-C 315.32, when the auditor identifies pervasive errors stemming from a common source, the auditor should reassess the risk of material misstatement for all affected assertions and expand procedures accordingly. The aggregate $72,000 approaching the $90,000 performance materiality heightens this concern. Choice B is incorrect because identifying the root cause increases rather than reduces the need for additional testing across all accounts affected by the flawed system.', 'medium', 3),

-- Q20: medium / L3 — Distinguishing design vs. operating deficiency in a scenario
(1, 'Misstatements and Control Deficiencies', 'Oakmont Financial Services has an accounts payable control requiring the AP clerk to match invoices, receiving reports, and purchase orders before processing payment. During the audit, Roberts & Kim CPAs find the matching control functions correctly when performed, but the AP clerk skips it for 30% of invoices due to workload pressure. This situation is best analyzed as:', '["A design deficiency because the control does not account for workload volume", "A material weakness because any control that is bypassed is automatically classified at the highest severity", "An inconsequential finding because the control works when it is performed", "An operating deficiency because a properly designed control is not being consistently executed"]'::jsonb, 3, 'Under AU-C 265.A1, a deficiency in operation exists when a properly designed control does not operate effectively. The three-way match is well designed but the clerk''s failure to execute it 30% of the time represents an operating failure. Choice A is incorrect because the control''s design is sound—the issue is not that the control fails to address workload but that personnel are not performing the control as designed.', 'medium', 3),

-- Q21: easy / L1 — Definition of a misstatement under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, a misstatement is defined as a difference between:', '["The auditor''s materiality threshold and the total errors found during testing", "The amount, classification, presentation, or disclosure of a reported item and what is required under the applicable framework", "Management''s estimates and the auditor''s independent point estimates for the same items", "The prior-year audited balances and the current-year unaudited balances"]'::jsonb, 1, 'Under AU-C 450.04, a misstatement is a difference between the reported amount, classification, presentation, or disclosure of a financial statement item and what is required under the applicable financial reporting framework. This encompasses errors in amounts, categorization, and disclosures. Choice A is incorrect because materiality is the auditor''s evaluation threshold, not one side of the comparison that defines a misstatement.', 'easy', 1),

-- Q22: hard / L4 — Remediated material weakness still requires written communication
(1, 'Misstatements and Control Deficiencies', 'During interim audit procedures for Sterling Aerospace Inc. in August 2025, the engagement team identifies a material weakness in the revenue recognition process. Management immediately implements new controls and by December 2025 the auditor confirms the remediation is effective. The engagement partner must determine the reporting obligation. Under AU-C 265, the auditor should:', '["Communicate the material weakness in writing to those charged with governance even though it was remediated before year-end", "Omit the material weakness from the written communication since it was fully remediated before the balance sheet date", "Downgrade the finding to a significant deficiency in the written communication to reflect the remediation", "Communicate only the remediation to those charged with governance without referencing the original weakness"]'::jsonb, 0, 'Under AU-C 265.13, the auditor is required to communicate all identified material weaknesses in writing to those charged with governance, regardless of whether they were subsequently remediated. The communication may note the remediation, but the identification itself must still be reported. Choice B is incorrect because remediation does not eliminate the reporting obligation—the material weakness existed during the audit period and governance must be informed.', 'hard', 4),

-- Q23: easy / L1 — Summary of uncorrected misstatements attached to rep letter
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the summary of uncorrected misstatements that accompanies the management representation letter should include:', '["Only misstatements that individually exceed overall materiality", "Only misstatements that management has agreed are errors", "All accumulated misstatements that are not clearly trivial, whether or not management agrees they are misstatements", "Only those misstatements the auditor considers material to the financial statements"]'::jsonb, 2, 'Under AU-C 450.14, the summary attached to the representation letter should include all uncorrected misstatements accumulated during the audit other than those that are clearly trivial. This ensures both the auditor and management have a complete record of known uncorrected items. Choice A is incorrect because the summary is not limited to individually material misstatements—it includes all accumulated misstatements regardless of individual size.', 'easy', 1),

-- Q24: easy / L1 — Factual misstatement from incorrect GAAP application
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, a misstatement that results from management''s incorrect application of accounting principles is classified as:', '["A projected misstatement derived from audit sampling", "A judgmental misstatement involving subjective estimates", "An immaterial error requiring no further evaluation", "A factual misstatement involving no uncertainty"]'::jsonb, 3, 'Under AU-C 450.A4, a factual misstatement is one about which there is no doubt. When management incorrectly applies an accounting principle—such as using the wrong recognition criteria—the resulting error is factual because the correct treatment is determinable and not subject to estimation uncertainty. Choice B is incorrect because judgmental misstatements arise from differences in management''s subjective estimates, not from clear misapplications of accounting principles.', 'easy', 1),

-- Q25: easy / L1 — Threshold distinction between significant deficiency and material weakness
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the key distinction between a significant deficiency and a material weakness is the:', '["Type of financial statement account affected by the control deficiency", "Magnitude and likelihood of potential misstatement that could result from the deficiency", "Number of transactions processed through the deficient control during the period", "Level of management responsible for the deficient control"]'::jsonb, 1, 'Under AU-C 265.07, both significant deficiencies and material weaknesses involve deficiencies in internal control, but a material weakness is distinguished by the reasonable possibility that a material misstatement will not be prevented or detected—a higher magnitude and likelihood threshold. Choice A is incorrect because the account type alone does not determine severity; the evaluation focuses on the potential magnitude and likelihood of resulting misstatements.', 'easy', 1),

-- Q26: medium / L2 — Projected misstatement exceeding tolerable misstatement
(1, 'Misstatements and Control Deficiencies', 'While auditing Meridian Supply Co., the engagement team sets tolerable misstatement for accounts receivable at $45,000. A sample of 60 invoices from a population of 1,200 reveals $3,800 in overstatement errors. The projected misstatement to the population is $76,000. Under AU-C 530, the auditor''s most appropriate response is to:', '["Conclude that the account may be materially misstated because the projected misstatement exceeds tolerable misstatement", "Accept the account balance because the actual errors found in the sample are below tolerable misstatement", "Request management to write off exactly $76,000 from accounts receivable", "Increase the tolerable misstatement to $80,000 to accommodate the projected amount"]'::jsonb, 0, 'Under AU-C 530.A20, when the projected misstatement exceeds tolerable misstatement, the sample results suggest the account may be materially misstated and the auditor should consider requesting management to investigate and expanding testing. Choice B is incorrect because the evaluation must consider the projected misstatement to the entire population, not just the actual sample errors—the $3,800 projects to $76,000, exceeding the $45,000 threshold.', 'medium', 2),

-- Q27: hard / L3 — Cascade effect of segregation-of-duties weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Timberline Construction LLC, Adams & Patel CPAs discover that the same employee initiates purchase orders, approves vendor invoices, and processes payments. The auditor confirms no compensating controls exist. Total disbursements processed through this employee are $4.2 million against overall materiality of $175,000. The auditor should analyze this finding as:', '["A significant deficiency because the employee''s dual roles have not yet resulted in a detected misstatement", "An operating deficiency limited to the purchasing function with no broader audit implications", "A material weakness because the lack of segregation of duties creates a reasonable possibility of undetected material misstatement in disbursements", "A control deficiency that can be mitigated by increasing the sample size for accounts payable confirmations"]'::jsonb, 2, 'Under AU-C 265.A11, when evaluating severity, the auditor considers the potential magnitude of misstatement and the likelihood of occurrence. With one employee controlling the entire disbursement cycle over $4.2 million and no compensating controls, there is a reasonable possibility that a material misstatement could occur undetected—meeting the AU-C 265.07 definition of material weakness. Choice A is incorrect because the absence of a detected misstatement does not reduce severity when the control gap makes detection itself unlikely.', 'hard', 3),

-- Q28: medium / L2 — Evaluating whether management's correction was appropriate
(1, 'Misstatements and Control Deficiencies', 'During the audit of Falcon Enterprises Inc., the engagement team identifies a $28,000 understatement of accrued liabilities. Management agrees to record the adjustment but posts it as an increase to accounts payable rather than accrued liabilities. Under AU-C 450, the auditor should:', '["Accept the correction because the total liabilities are correctly stated on the balance sheet", "Treat the original misstatement as resolved and remove it from the summary of uncorrected items", "Report the classification issue only if it exceeds performance materiality", "Evaluate whether the incorrect classification constitutes a new misstatement in financial statement presentation"]'::jsonb, 3, 'Under AU-C 450.04, misstatements include errors in classification, not just amounts. Although management corrected the dollar amount, posting the accrual to accounts payable rather than accrued liabilities creates a classification misstatement that may affect financial statement presentation and must be evaluated. Choice A is incorrect because proper classification between liability accounts matters for fair presentation—a correct total does not cure a classification misstatement.', 'medium', 2),

-- Q29: hard / L4 — Entity-level control deficiency and overall audit strategy
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westbrook Holdings Corp., the engagement team discovers that the CFO routinely overrides the monthly close process, posting unsupported journal entries without review. The CEO is aware but considers it necessary for meeting deadlines. The board''s audit committee meets only annually and reviews summary financial data. Under AU-C 265 and AU-C 315, the most appropriate response is to:', '["Document the override as a deficiency in operation and proceed with the planned substantive testing approach", "Evaluate the combined deficiencies as an entity-level material weakness that fundamentally affects the overall audit strategy and the auditor''s report", "Limit additional procedures to journal entry testing since that is the specific area of override", "Communicate the findings to the audit committee and postpone further audit work until remediation occurs"]'::jsonb, 1, 'Under AU-C 265.A7 and AU-C 315.A77, management override of controls, weak governance oversight, and an ineffective control environment represent entity-level deficiencies that permeate the entire financial reporting process. These combined weaknesses constitute a material weakness requiring a fundamental reassessment of the audit strategy. Choice C is incorrect because entity-level control deficiencies affect all assertions and accounts, requiring a comprehensive response rather than procedures limited to one area.', 'hard', 4),

-- Q30: medium / L2 — Communication obligation for immaterial fraud involving management
(1, 'Misstatements and Control Deficiencies', 'While auditing Bayshore Retail Group, the engagement team discovers that the assistant controller embezzled $2,100 by creating fictitious vendor invoices over three months. Overall materiality is $350,000 and the clearly trivial threshold is $7,000. Under AU-C 240, the auditor''s communication obligation is to:', '["Communicate the fraud to those charged with governance because it involves a member of management regardless of the dollar amount", "Treat the finding as clearly trivial and omit it from all audit communications", "Report the fraud only to the assistant controller''s direct supervisor for corrective action", "Defer communication until the annual governance letter is issued after year-end"]'::jsonb, 0, 'Under AU-C 240.40-.41, the auditor must communicate identified fraud to the appropriate level of management on a timely basis and must communicate to those charged with governance any fraud involving senior management. An assistant controller with financial reporting duties is part of management, triggering this obligation regardless of amount. Choice B is incorrect because the clearly trivial threshold applies to misstatement accumulation under AU-C 450, not to the separate fraud communication requirements under AU-C 240.', 'medium', 2)
;

COMMIT;
